function dealerCallDecision(callAmount){const h=state.hand,street=currentStreet(),psych=h.psych?.[street]||ensurePsych(street),equity=Number(psych?.equity)||.5,pot=round2(h.studentStake+h.dealerStake),potOdds=callAmount/Math.max(.1,pot+callAmount),available=availableForCommitment('dealer');if(callAmount>available+1e-9)return{action:'fold',reason:'No puede igualar sin superar el máximo de 0.50 por mano o su banca disponible.'};let threshold=potOdds+.10;if(street==='turn')threshold+=.02;if(street==='river')threshold+=.05;if(callAmount>=.3)threshold+=.04;const cautionNoise=(Math.random()-.5)*.06,score=equity+cautionNoise;if(score+1e-9<threshold)return{action:'fold',reason:`La probabilidad interna ${(equity*100).toFixed(0)}% no compensa el riesgo de igualar ${money(callAmount)}.`};const roomAfterCall=round2(Math.max(0,available-callAmount)),raiseGate=street==='preflop'?.73:street==='flop'?.69:street==='turn'?.66:.71;let raiseExtra=0;if(roomAfterCall>=.1&&equity>=raiseGate){const raiseProb=clamp(.10+(equity-raiseGate)*.80,0,.34);if(Math.random()<raiseProb){raiseExtra=.1;if(roomAfterCall>=.2&&equity>=raiseGate+.11&&Math.random()<.34)raiseExtra=.2;raiseExtra=round2(Math.min(raiseExtra,roomAfterCall))}}if(raiseExtra>0)return{action:'raise',raiseExtra,reason:`La Mesa estima ${(equity*100).toFixed(0)}% de éxito: iguala con cautela y resube ${money(raiseExtra)}.`};return{action:'call',reason:`La Mesa considera suficiente su probabilidad interna ${(equity*100).toFixed(0)}% para igualar, pero no para resubir.`}}
