   if(r.finishedAt){if(r.correct>=2){idx=0;signalLabel='Golpeado, pero contenido';tell='Tus dos respuestas correctas neutralizaron la pérdida y su gesto acusa el golpe.'}else if(r.correct===1){idx=1;signalLabel='Recomponiéndose';tell='Tu rescate parcial reduce el impacto y la Mesa vuelve a calcular.'}else{idx=4;signalLabel='Maestro de la mesa';tell='El rescate no redujo la pérdida y recupera una seguridad dominante.'}}
