function preflopTexture(hole){const vals=hole.map(P.rankValue).sort((a,b)=>b-a),hi=vals[0],lo=vals[1],pair=hi===lo,suited=hole[0][1]===hole[1][1],gap=Math.abs(hi-lo),bothBroadway=hi>=10&&lo>=10;let score=.34;if(pair)score=.56+hi/28;else{score+=(hi-7)/22;if(lo>=10)score+=.08;if(suited)score+=.06;if(gap<=1)score+=.08;else if(gap===2)score+=.04;if(bothBroadway)score+=.08;if(hi===14&&lo>=10)score+=.06;}return clamp(score,.1,.95)}
