function persistGenius(cq){const g=cq?.learning?.genie;if(!g?.threadId)return Promise.resolve(false);return GM.GenieMemory.save(g.threadId,{questionId:cq.qId,turns:g.turns||[],summary:g.summary||'',studentModel:g.studentModel,interventions:g.interventions||[],interactions:g.interactions||0,requestCount:g.requestCount||0,loopPrevented:g.loopPrevented||0,providers:g.providers||[]})}
async function restoreGenius(cq){const g=ensureLearningCycle(cq).genie;if(g.memoryLoaded)return;g.memoryLoaded=true;const stored=await GM.GenieMemory.load(g.threadId);if(state.currentQuestion!==cq||cq.submitted)return;if(stored){const m=new Map((stored.turns||[]).map(t=>[t.id||`${t.at}:${t.role}:${t.text}`,t]));for(const t of g.turns)m.set(t.id||`${t.at}:${t.role}:${t.text}`,t);g.turns=[...m.values()].sort((a,b)=>a.at-b.at);if((stored.interactions||0)>=(g.interactions||0)){g.summary=stored.summary||g.summary;g.studentModel=stored.studentModel||g.studentModel;g.interventions=stored.interventions||g.interventions;g.interactions=stored.interactions||g.interactions;g.loopPrevented=stored.loopPrevented||g.loopPrevented;g.providers=stored.providers||g.providers}g.requestCount=Math.max(g.requestCount||0,stored.requestCount||0)}renderGenieChat(cq)}
function closeGeniusPanel(){const cq=state.currentQuestion;cancelGenius();if(cq&&!cq.submitted&&cq.phase==='genie')cq.phase='independent';GM.TutorPanel.hide();saveState(true);syncQuestionPhaseUI();$('hintBtn')?.focus()}
function restoreAnswerDraft(cq){const host=$('answerArea'),q=QB.get(cq.qId),raw=cq.answerDraft;if(raw===undefined||raw===null)return;if(q.type==='mcq')host.querySelectorAll('input[type=radio]').forEach(el=>el.checked=el.value===String(raw));else{const el=host.querySelector('.numeric-answer');if(el)el.value=String(raw)}if(cq.confidenceDraft)$('qConfidence').value=cq.confidenceDraft}
function captureAnswerDraft(){const cq=state.currentQuestion;if(!cq||cq.submitted)return;cq.answerDraft=readAnswer(QB.get(cq.qId),$('answerArea'),'qans');cq.confidenceDraft=$('qConfidence').value;saveLocal()}
function studentAttemptBlocked(){if(!isLmsStudent())return false;return !!SCORM?.getAttempt?.().completed||completedAttempt().length>0}

function ensureLearningCycle(cq){if(!cq)return null;cq.phase=cq.phase||(!cq.submitted?'independent':'transfer');cq.learning=cq.learning||{};const g=cq.learning.genie=cq.learning.genie||{};g.turns=Array.isArray(g.turns)?g.turns:[];g.openedBeforeAnswer=!!g.openedBeforeAnswer;g.threadId=g.threadId||`t72:${identityKey()}:${cq.startedAt}:${cq.qId}`;g.studentModel=g.studentModel||GM.StudentModel.create();g.summary=g.summary||'';g.interventions=Array.isArray(g.interventions)?g.interventions:[];g.interactions=Number(g.interactions)||0;g.requestCount=Math.max(Number(g.requestCount)||0,g.turns.filter(t=>t.role==='student').length);return cq.learning}
function phaseRank(p){return{independent:0,genie:1,transfer:2,complete:3}[p]??0}
function renderQuestionPhaseTrack(cq){const rank=phaseRank(cq.phase);document.querySelectorAll('#qLearningTrack [data-qphase]').forEach((el,i)=>{el.classList.toggle('done',i<rank);el.classList.toggle('active',i===Math.min(rank,2)&&cq.phase!=='complete')});if(cq.phase==='complete')document.querySelectorAll('#qLearningTrack [data-qphase]').forEach(el=>el.classList.add('done'))}
function renderGenieChat(cq){const host=$('genieChat'),g=ensureLearningCycle(cq)?.genie;if(!host||!g)return;host.replaceChildren();if(!g.turns.length){const empty=document.createElement('p');empty.className='genius-empty';empty.textContent='Tu conversación sobre este ejercicio aparecerá aquí. Puedes compartir una duda, una fórmula que no recuerdes o los pasos que has escrito.';host.append(empty)}for(const t of g.turns.slice(-100)){if(t.notice)continue;const box=document.createElement('div');box.className='genius-msg '+(t.role==='student'?'student':'assistant');const author=document.createElement('span');author.className='message-author';author.textContent=t.role==='student'?'Tú':'Genius';const body=document.createElement('div');body.className='message-body';body.textContent=t.text;box.append(author,body);host.append(box)}renderMath(host);host.scrollTop=host.scrollHeight;GM.TutorPanel.refresh()}
function addGenieGreeting(cq,q){const g=ensureLearningCycle(cq).genie;g.openedBeforeAnswer=true;cq.assisted_before_first_answer=true;cq.independent_first_attempt=false;void restoreGenius(cq)}
function renderTransferQuestion(cq){const t=cq.learning?.transfer;if(!t?.qId)return;const q=QB.get(t.qId);if(!q)return;$('transferMeta').textContent=`${q.id} · ${q.topic} · mismo concepto · decisión diferente`;renderAcademicPrompt(q,$('transferPrompt'));renderAnswerArea(q,$('transferAnswerArea'),'transans');if(t.draft!=null){const host=$('transferAnswerArea');if(q.type==='mcq')host.querySelectorAll('input[type=radio]').forEach(el=>el.checked=el.value===String(t.draft));else{const el=host.querySelector('.numeric-answer');if(el)el.value=String(t.draft)}}$('transferForm').classList.toggle('hidden',!!t.submitted);const fb=$('transferFeedback');if(t.submitted){fb.className=`feedback ${t.correct?'good':'bad'}`;fb.innerHTML=`${t.correct?'Transferencia correcta.':'Transferencia incorrecta.'} ${q.explanation||''}`;renderMath(fb)}else{fb.className='feedback hidden';fb.innerHTML=''}renderMath($('transferPrompt'));renderMath($('transferAnswerArea'))}
function syncQuestionPhaseUI(){const cq=state.currentQuestion;if(!cq)return;ensureLearningCycle(cq);const q=QB.get(cq.qId);renderQuestionPhaseTrack(cq);for(const id of ['answerForm','geniePanel','transferPanel','changeDecision','wrongCloseWrap','qHint'])$(id).classList.add('hidden');$('questionModal').classList.remove('genius-open');const fb=$('qFeedback');fb.className='feedback hidden';fb.innerHTML='';$('qClose').disabled=false;
 if(cq.phase==='independent'){$('qPhaseNote').textContent='Exploración inicial · Resuelve con tus recursos o abre Genius antes de responder.';$('answerForm').classList.remove('hidden');$('hintBtn').disabled=false;$('hintBtn').textContent='✦ ABRIR GENIUS MATH';return}
 if(cq.phase==='genie'){addGenieGreeting(cq,q);$('qPhaseNote').textContent='Aprendizaje con Genius · Puedes conversar y volver al ejercicio cuando lo necesites.';$('answerForm').classList.remove('hidden');$('hintBtn').disabled=false;$('hintBtn').textContent='✦ GENIUS MATH';GM.TutorPanel.show();renderGenieChat(cq);if(cq.learning.genie.guideUsed&&GM.ModelProvider.current().kind==='guided')GM.TutorPanel.references(q);return}
 if(cq.phase==='transfer'){cancelGenius();$('qPhaseNote').textContent='Transferencia sin IA · Aplica lo aprendido a una decisión matemática distinta.';$('transferPanel').classList.remove('hidden');$('hintBtn').disabled=true;$('hintBtn').textContent='🔒 SIN GENIUS EN TRANSFERENCIA';$('qClose').disabled=true;renderTransferQuestion(cq);return}
 const assisted=!!cq.learning.genie.openedBeforeAnswer;$('qPhaseNote').textContent='Ciclo pedagógico completado.';$('hintBtn').disabled=true;$('hintBtn').textContent='✓ CICLO COMPLETADO';fb.className=`feedback ${cq.correct?'good':'bad'}`;fb.innerHTML=`<b>Primera respuesta: ${cq.correct?'correcta':'incorrecta'}.</b> ${assisted?'Abriste Genius antes de responder.':'Respondiste sin abrir Genius.'} ${q.explanation||''}<br><span class="genius-cycle-complete">La transferencia se resolvió sin IA y no modifica la nota oficial.</span>`;renderMath(fb);if(cq.learning.transfer?.submitted){$('transferPanel').classList.remove('hidden');renderTransferQuestion(cq)}if(cq.correct){const op=opFor(cq.target.zone,cq.target.index,cq.target.street);if(op)op.status='correct_pending';showDecision(q,cq)}else{const op=opFor(cq.target.zone,cq.target.index,cq.target.street);if(op)op.status='wrong';$('wrongCloseWrap').classList.remove('hidden')}
}
function openQuestionModal(){cancelGenius();const cq=state.currentQuestion;if(!cq)return;ensureLearningCycle(cq);const q=QB.get(cq.qId);$('qMeta').textContent=`${q.id} · ${q.topic}${q.hasGraphic?' · 📈 GRÁFICA':''} · ${questionTargetText(cq.target)}`;$('qTitle').textContent='Reto EDO · ciclo Genius Math';renderAcademicPrompt(q,$('qPrompt'));$('qHint').innerHTML='';renderAnswerArea(q,$('answerArea'),'qans');restoreAnswerDraft(cq);$('genieInput').value=cq.learning.genie.draft||'';$('questionModal').classList.remove('hidden');renderMath($('qPrompt'));renderMath($('answerArea'));syncQuestionPhaseUI()}
function openPreAnswerGenius(){const cq=state.currentQuestion;if(!cq||cq.submitted||!['independent','genie'].includes(cq.phase))return;const q=QB.get(cq.qId);if(cq.phase==='independent')cq.phase='genie';addGenieGreeting(cq,q);state.lastEvent='Genius Math abierto antes de registrar la respuesta.';saveState(true);syncQuestionPhaseUI();setTimeout(()=>$('genieInput')?.focus(),40)}
async function askGeniusMath(ev){ev?.preventDefault?.();const cq=state.currentQuestion;if(!cq||cq.submitted||!['independent','genie'].includes(cq.phase)||geniusAbort)return;if(cq.phase==='independent')openPreAnswerGenius();const q=QB.get(cq.qId),input=$('genieInput'),message=String(input.value||'').trim();if(!message)return;const provider=GM.ModelProvider.current();if(!provider.generative||!provider.ready){GM.TutorPanel.status('Activa la IA para conversar. La guía de fórmulas no es un chat.');return}const g=ensureLearningCycle(cq).genie;g.turns.push({id:GM.util.id(),role:'student',text:message,at:Date.now()});g.requestCount++;g.draft='';input.value='';renderGenieChat(cq);const controller=geniusAbort=new AbortController(),run=++geniusRun;GM.TutorPanel.setBusy(true);GM.TutorPanel.status('Genius está pensando…');void persistGenius(cq);saveLocal();try{const result=await GM.GenieEngine.ask({question:q,cycle:cq,message,sessionId:currentAttemptId(),signal:controller.signal});if(run!==geniusRun||state.currentQuestion!==cq||cq.submitted||controller.signal.aborted)return;g.lastRuntime={modelId:provider.model||null,liveInference:provider.liveInference===true,ready:provider.ready===true};g.helpLevel=Math.max(Number(g.helpLevel)||0,Number(result.helpLevel)||0);g.turns.push({id:GM.util.id(),role:'assistant',text:result.text,at:Date.now(),strategy:result.strategy,semantic_key:result.semantic_key});GM.TutorPanel.status('Puedes seguir conversando o volver a tu respuesta.');recordToolEvent('Genius Math',`${q.id} · consulta pedagógica`);const ok=await persistGenius(cq);if(!ok)GM.TutorPanel.status('La explicación está disponible, pero no se pudo guardar el historial extenso en este navegador.')}catch(e){if(run===geniusRun&&!cq.submitted)GM.TutorPanel.status(e.name==='AbortError'?'Generación cancelada.':e.message)}finally{if(run===geniusRun){geniusAbort=null;GM.TutorPanel.setBusy(false);if(state.currentQuestion===cq){renderGenieChat(cq);saveState(true)}}}}
function focusAnswerAfterGenius(){closeGeniusPanel();$('answerForm')?.scrollIntoView({behavior:'smooth',block:'center'});$('answerArea')?.querySelector('input,button')?.focus()}
function beginTransfer(){const cq=state.currentQuestion;if(!cq||!cq.submitted||!['independent','genie'].includes(cq.phase))return;cancelGenius();const base=QB.get(cq.qId),tq=GM.PedagogyEngine.selectTransfer(base,state.usedQuestions);if(!tq){state.lastEvent='No hay una transferencia compatible; se requiere revisión docente.';GM.TutorPanel.status(state.lastEvent);return}const info=GM.PedagogyEngine.transferInfo(base,tq);cq.learning.transfer={qId:tq.id,startedAt:Date.now(),submitted:false,answer:null,correct:null,seconds:0,reason:info.reason,sharedConcept:info.sharedConcept,previouslySeen:state.usedQuestions.includes(tq.id)};cq.phase='transfer';updateQuestionLearningRecord(cq);state.lastEvent=`Primera respuesta registrada. Transferencia sin IA ${tq.id}.`;void persistGenius(cq);recordToolEvent('Transferencia iniciada',`${cq.qId} → ${tq.id}`);saveState(true);syncQuestionPhaseUI()}
function updateQuestionLearningRecord(cq){const r=Number.isInteger(cq.historyIndex)?state.questionHistory[cq.historyIndex]:null;if(!r)return;const g=cq.learning?.genie||{},t=cq.learning?.transfer||null;r.independent_first_attempt=!g.openedBeforeAnswer;r.assisted_before_first_answer=!!g.openedBeforeAnswer;r.base_performance=!!cq.correct;r.help_used=!!g.openedBeforeAnswer;r.transfer_performance=t?.submitted?!!t.correct:null;r.genius={providers:GM.util.unique(g.providers||[]),localModel:g.lastRuntime?.modelId||null,localInferenceUsed:g.lastRuntime?.liveInference===true,runtimeAvailable:g.lastRuntime?.ready??null,turns:Number(g.requestCount)||0,interactions:Number(g.interactions)||0,helpLevel:Number(g.helpLevel)||0,openedBeforeAnswer:!!g.openedBeforeAnswer,guideUsed:!!g.guideUsed,summary:String(g.summary||'').slice(0,950),concepts:g.studentModel?.concepts||[],formulas:GM.util.unique([...(g.studentModel?.formulas||[]),...(g.guideFormulaIds||[])]),errors:g.studentModel?.errors||[],confidence:g.studentModel?.confidence??null,threadId:g.threadId};r.transfer=t?{id:t.qId,answer:t.answer,submitted:!!t.submitted,correct:t.submitted?!!t.correct:null,seconds:Number(t.seconds)||0,reason:t.reason,previouslySeen:!!t.previouslySeen}:null;r.hintUsed=!!g.openedBeforeAnswer}
function submitTransferQuestion(ev){ev.preventDefault();const cq=state.currentQuestion,t=cq?.learning?.transfer;if(!cq||cq.phase!=='transfer'||!t||t.submitted)return;const q=QB.get(t.qId),raw=readAnswer(q,$('transferAnswerArea'),'transans');if(!answerPresent(q,raw)){alert('Completa la respuesta de transferencia.');return}t.answer=answerToText(q,raw);t.correct=answerCorrect(q,raw);t.seconds=Math.max(1,Math.round((Date.now()-t.startedAt)/1000));t.submitted=true;if(!state.usedQuestions.includes(q.id))state.usedQuestions.push(q.id);cq.phase='complete';updateQuestionLearningRecord(cq);state.lastEvent=`Transferencia ${t.correct?'correcta':'incorrecta'} después de Genius Math. La nota oficial no cambia por esta fase.`;recordToolEvent('Transferencia completada',`${q.id} · ${t.correct?'correcta':'incorrecta'} · sin efecto en nota`);playTone(t.correct?700:280,.06,t.correct?'sine':'triangle');saveState(true);syncQuestionPhaseUI()}
function orderLabel(i){return String.fromCharCode(65+i)}
function renderOrderAnswer(q,host,name,withCalc=false){
 const steps=Array.isArray(q.steps)?q.steps:[],labels=steps.map((s,i)=>({id:String(s.id),label:orderLabel(i),text:String(s.text||'')}));
 const source=`<div class="order-source"><b>Pasos disponibles</b>${labels.map(x=>`<div class="order-source-row"><span>${x.label}</span><div>${esc(x.text)}</div></div>`).join('')}</div>`;
 const selects=`<div class="order-slots"><b>Orden que propones</b><div class="order-slot-grid">${labels.map((_,i)=>`<label><span>${i+1}</span><select data-order-pos="${i}" name="${name}_ord_${i}"><option value="">—</option>${labels.map(x=>`<option value="${esc(x.id)}">${x.label}</option>`).join('')}</select></label>`).join('')}</div></div>`;
 let calc='';
 if(withCalc){calc=`<div class="order-calc"><h4>${esc(q.calcTitle||'Cálculo final')}</h4><div class="order-calc-prompt">${String(q.calcPrompt||'')}</div><div class="order-calc-grid">${(q.calcFields||[]).map((f,i)=>`<label><span>${esc(f.label||f.key)}</span><input class="numeric-answer compact" data-calc-key="${esc(f.key)}" inputmode="decimal" autocomplete="off" placeholder="Respuesta"></label>`).join('')}</div></div>`}
 host.innerHTML=source+selects+calc;
}
function renderAnswerArea(q,host,name){
 if(q.type==='mcq'){host.innerHTML=`<div class="answer-options">${q.options.map((o,i)=>`<div class="answer-option"><input type="radio" name="${name}" id="${name}${i}" value="${esc(o)}"><label for="${name}${i}">${esc(o)}</label></div>`).join('')}</div>`;return}
 if(q.type==='order'){renderOrderAnswer(q,host,name,false);return}
 if(q.type==='ordercalc'){renderOrderAnswer(q,host,name,true);return}
 host.innerHTML='<input class="numeric-answer" inputmode="decimal" autocomplete="off" placeholder="Escribe tu respuesta; se acepta a/b">';
}
function readAnswer(q,host,name){
 if(q.type==='mcq')return host.querySelector(`input[name="${name}"]:checked`)?.value??null;
 if(q.type==='order'||q.type==='ordercalc'){
   const order=[...host.querySelectorAll('[data-order-pos]')].sort((a,b)=>Number(a.dataset.orderPos)-Number(b.dataset.orderPos)).map(x=>x.value||'');
   if(q.type==='order')return{order};
   const calc={};for(const input of host.querySelectorAll('[data-calc-key]'))calc[input.dataset.calcKey]=input.value??'';return{order,calc};
 }
 return host.querySelector('input')?.value??'';
}
function orderIsCorrect(q,raw){const order=raw?.order;if(!Array.isArray(order)||order.length!==(q.steps||[]).length||order.some(x=>!x))return false;return(q.validOrders||[]).some(valid=>valid.length===order.length&&valid.every((id,i)=>String(id)===String(order[i])))}
function answerPresent(q,raw){
 if(q.type==='mcq')return raw!==null&&String(raw).trim()!=='';
 if(q.type==='order')return Array.isArray(raw?.order)&&raw.order.length===(q.steps||[]).length&&raw.order.every(Boolean);
 if(q.type==='ordercalc')return Array.isArray(raw?.order)&&raw.order.length===(q.steps||[]).length&&raw.order.every(Boolean)&&(q.calcFields||[]).every(f=>String(raw?.calc?.[f.key]??'').trim()!=='');
 return raw!==null&&String(raw).trim()!=='';
}
function answerToText(q,raw){
 if(q.type==='order'||q.type==='ordercalc'){
   const labels=new Map((q.steps||[]).map((s,i)=>[String(s.id),orderLabel(i)])),ord=(raw?.order||[]).map(id=>labels.get(String(id))||String(id)).join(' → ');
   if(q.type==='order')return ord;
   const nums=(q.calcFields||[]).map(f=>`${f.label||f.key}=${raw?.calc?.[f.key]??''}`).join('; ');return `${ord} | ${nums}`;
 }
 return String(raw??'');
}
function answerCorrect(q,raw){
 if(q.type==='mcq')return String(raw)===String(q.answer);
 if(q.type==='order')return orderIsCorrect(q,raw);
 if(q.type==='ordercalc'){
   if(!orderIsCorrect(q,raw))return false;
   return(q.calcFields||[]).every(f=>{const n=parseNumeric(raw?.calc?.[f.key]);return Number.isFinite(n)&&Math.abs(n-Number(f.answer))<=Math.max(f.tolerance||1e-8,Math.abs(Number(f.answer))*1e-6)});
 }
 const n=parseNumeric(raw);return Number.isFinite(n)&&Math.abs(n-Number(q.answer))<=Math.max(q.tolerance||1e-8,Math.abs(Number(q.answer))*1e-6);
}
function parseNumeric(s){s=String(s||'').trim().replace(',','.');if(/^[-+]?\d+(\.\d+)?\s*\/\s*[-+]?\d+(\.\d+)?$/.test(s)){const[a,b]=s.split('/').map(Number);return b!==0?a/b:NaN}return Number(s)}
function submitNormalQuestion(ev){ev.preventDefault();const cq=state.currentQuestion;if(!cq||cq.submitted||!['independent','genie'].includes(cq.phase))return;const q=QB.get(cq.qId),raw=readAnswer(q,$('answerArea'),'qans');if(!answerPresent(q,raw)){alert('Completa la respuesta. Si estás perdido, puedes pedir una fórmula o una pista a Genius Math antes de responder.');return}const answerText=answerToText(q,raw),ok=answerCorrect(q,raw),elapsed=Math.max(1,Math.round((Date.now()-cq.startedAt)/1000)),confidence=$('qConfidence')?.value||'medium',g=ensureLearningCycle(cq).genie,assisted=Number(g.helpLevel||0)>0||!!g.openedBeforeAnswer;cancelGenius();cq.submitted=true;cq.independent_first_attempt=!g.openedBeforeAnswer;cq.assisted_before_first_answer=!!g.openedBeforeAnswer;cq.correct=ok;cq.answer=answerText;cq.learning.independent={answer:answerText,correct:ok,seconds:elapsed,confidence,assistedBeforeAnswer:assisted,helpLevelBeforeAnswer:Number(g.helpLevel)||0};state.usedQuestions.push(q.id);if(ok)state.C++;else state.I++;const rec={id:q.id,kind:'normal',topic:q.topic,target:questionTargetText(cq.target),answer:answerText,correct:ok,seconds:elapsed,street:cq.target.street,decision:null,hintUsed:assisted,confidence,assistedBeforeAnswer:assisted,helpLevelBeforeAnswer:Number(g.helpLevel)||0,at:Date.now(),genius:null,transfer:null};state.questionHistory.push(rec);cq.historyIndex=state.questionHistory.length-1;g.summary=g.summary||'';updateQuestionLearningRecord(cq);state.lastEvent=assisted?'Primera respuesta registrada después de abrir Genius Math. Inicia transferencia sin IA.':'Primera respuesta registrada sin usar Genius Math. Inicia transferencia sin IA.';playTone(ok?620:400,.05);saveState(true);renderHUD();beginTransfer()}
function showDecision(q,cq){cq.awaitingDecision=true;$('changeDecision').classList.remove('hidden');$('decisionText').textContent=cq.target.zone==='dealer'?'No verás ni la carta original ni la nueva. El cambio puede ayudar o perjudicar a la Mesa.':'El reemplazo sale al azar del mazo restante; puede mejorar o empeorar tu situación.';$('qClose').disabled=true}
function decisionCard(change){const cq=state.currentQuestion;if(!cq||!cq.correct)return;const op=opFor(cq.target.zone,cq.target.index,cq.target.street);const old=targetCard(cq.target);let fresh=null;if(change){fresh=drawCard();state.hand.discard.push(old);setTargetCard(cq.target,fresh);op.status='changed';state.hand.changes.push({street:cq.target.street,zone:cq.target.zone,index:cq.target.index,old,new:fresh,at:Date.now()});state.lastEvent=cq.target.zone==='dealer'?`Cambiaste al azar una carta oculta de la Mesa.`:`Carta cambiada: ${P.label(old)} → ${P.label(fresh)}.`;const qh=[...state.questionHistory].reverse().find(x=>x.id===cq.qId&&x.decision===null);if(qh)qh.decision=`cambiar ${old}->${fresh}`;if(cq.target.zone==='dealer'||cq.target.zone==='board')refreshPsych(cq.target.street);playTone(650,.05)}else{op.status='kept';state.lastEvent=cq.target.zone==='dealer'?'Decidiste no alterar esa carta oculta de la Mesa.':`Conservaste ${P.label(old)}.`;const qh=[...state.questionHistory].reverse().find(x=>x.id===cq.qId&&x.decision===null);if(qh)qh.decision='conservar'}state.currentQuestion=null;$('questionModal').classList.add('hidden');$('qClose').disabled=false;saveState(true);render()}
function closeQuestion(){cancelGenius();const cq=state.currentQuestion;if(!cq){$('questionModal').classList.add('hidden');return}ensureLearningCycle(cq);if(cq.awaitingDecision){alert('Elige Conservar o Cambiar para cerrar esta oportunidad.');return}if(cq.phase==='transfer'){alert('Completa primero la prueba de transferencia sin IA.');return}if(cq.phase==='complete'){if(cq.correct){alert('Elige Conservar o Cambiar para cerrar esta oportunidad.');return}state.currentQuestion=null;$('questionModal').classList.add('hidden');render();return}if(cq.submitted){alert('Completa primero el ciclo pedagógico.');return}if(!confirm('La pregunta ya fue abierta. Si sales, esta carta perderá su oportunidad de pregunta sin sumar correcta ni incorrecta. ¿Continuar?'))return;const op=opFor(cq.target.zone,cq.target.index,cq.target.street);if(op)op.status='skipped';state.lastEvent='Oportunidad académica descartada sin responder.';state.currentQuestion=null;$('questionModal').classList.add('hidden');saveState(true);render()}
