const OP_ENC={available:'a',changed:'c',kept:'k',wrong:'w',skipped:'s',question_open:'o',correct_pending:'p'},OP_DEC={a:'available',c:'changed',k:'kept',w:'wrong',s:'skipped',o:'question_open',p:'correct_pending'};
function encOps(arr){return(arr||[]).map(o=>OP_ENC[o.status]||'s').join('')}
function decOps(str){return [...String(str||'')].map(x=>({status:OP_DEC[x]||'skipped'}))}
function compactPsych(psych){const out={};for(const [street,p] of Object.entries(psych||{})){out[street]={e:p.equity,ti:p.trueIdx,si:p.shownIdx,l:p.label,m:p.mood,v:p.value,tr:p.truthful?1:0,g:p.generatedAt,d:p.delta,pc:p.publicCategory,pn:p.publicName,tl:p.tell}}return out}
function expandPsych(psych){const out={};for(const [street,p] of Object.entries(psych||{})){out[street]={street,equity:Number(p.e)||.5,trueIdx:Number(p.ti)||0,shownIdx:Number(p.si)||0,label:p.l||'Analítico',mood:p.m||'studious',value:Number(p.v)||50,truthful:!!p.tr,generatedAt:Number(p.g)||Date.now(),delta:Number(p.d)||0,publicCategory:p.pc??null,publicName:p.pn||'',tell:p.tl||''}}return out}
function compactBets(bets){return(bets||[]).map(b=>[b.street,b.studentInc||0,b.dealerInc||0,b.studentTotal||0,b.dealerTotal||0,b.mandatory?1:0,b.action||'',b.side||'',b.at||0])}
function expandBets(bs,studentBlind,dealerBlind,startedAt){if(!Array.isArray(bs)||!bs.length)return[{street:'blinds',studentInc:round2(studentBlind),dealerInc:round2(dealerBlind),studentTotal:round2(studentBlind),dealerTotal:round2(dealerBlind),mandatory:true,action:'ciegas',at:startedAt}];return bs.map(x=>({street:x[0],studentInc:Number(x[1])||0,dealerInc:Number(x[2])||0,studentTotal:Number(x[3])||0,dealerTotal:Number(x[4])||0,mandatory:!!x[5],action:x[6]||'',side:x[7]||'',at:Number(x[8])||startedAt}))}
function compactChanges(changes){return(changes||[]).map(c=>[c.street,c.zone,c.index,c.old,c.new,c.at||0])}
