function compactHand(h){if(!h)return null;let sd=null;if(h.showdown)sd={winner:h.showdown.winner,fold:!!h.showdown.fold,folded:h.showdown.folded||null};let r=null;if(h.rescue)r={step:h.rescue.step,correct:h.rescue.correct,currentQId:h.rescue.currentQId,startedAt:h.rescue.startedAt,loss:h.rescue.loss,saved:h.rescue.saved,finishedAt:h.rescue.finishedAt,timeoutSettlement:h.rescue.timeoutSettlement,answers:(h.rescue.answers||[]).map(a=>[a.id,a.answer,a.correct?1:0,a.seconds||0,a.topic||''])};return{id:h.id,p:h.phase,st:h.street,d:(h.deck||[]).join(','),sh:(h.studentHole||[]).join(','),dh:(h.dealerHole||[]).join(','),b:(h.board||[]).join(','),o:{s:encOps(h.ops?.student),d:encOps(h.ops?.dealer),f:encOps(h.ops?.flop),t:encOps(h.ops?.turn),r:encOps(h.ops?.river)},bt:h.button==='dealer'?'d':'s',sbl:h.studentBlind,dbl:h.dealerBlind,ss:h.studentStake,ds:h.dealerStake,ps:compactPsych(h.psych),sd,r,br:h.betRound||null,bs:compactBets(h.bets),cg:compactChanges(h.changes),sa:h.startedAt}}
