function hydrateSuspend(s){const z=freshState();z.profileMode=s.pm||'student';z.profileLabel=z.profileMode==='student'?'ESTUDIANTE BRIGHTSPACE':z.profileMode==='teacher_tracked'?'DOCENTE / CON SEGUIMIENTO BRIGHTSPACE':z.profileMode==='teacher_without'?'DOCENTE / WITHOUT TRACKING, PREVIEW':z.profileMode==='teacher_preview'?'DOCENTE / PREVIEW':'MODO LOCAL';z.studentName=s.n||'';z.studentId=s.si||'';z.startedAt=Number(s.st)||Date.now();z.deadlineAt=Number(s.dl)||z.startedAt+TIME_LIMIT*1000;z.awaitingFinalize=!!s.af;z.gameActive=!s.fin&&!z.awaitingFinalize;z.finished=!!s.fin;z.grade=Number(s.g);if(!Number.isFinite(z.grade))z.grade=START_BANK;z.dealerScore=Number(s.m);if(!Number.isFinite(z.dealerScore))z.dealerScore=START_BANK;z.C=Number(s.c)||0;z.I=Number(s.i)||0;z.handNo=Number(s.hn)||0;z.firstButton=s.fb==='d'?'dealer':'student';z.selectedTopics=normalizeSelectedTopics(String(s.tp||'').split(',').filter(Boolean));z.usedQuestions=Array.isArray(s.uq)?s.uq:decodeUsed(s.uq);z.hand=s.h?.p?expandHand(s.h):(s.h||null);z.currentQuestion=s.cq||null;z.raiseChallenge=s.rc||null;z.lastEvent=s.le||'Partida recuperada desde SCORM.';z.finalGrade=s.fg??null;if(s.qr&&z.currentQuestion){z.questionHistory=[s.qr];z.currentQuestion.historyIndex=0}return z}
