function saveLocal(){try{const key=saveKey(),prof=userProfile();state.profileMode=prof.mode;state.profileLabel=prof.label;const snapshot={...state,currentQuestion:compactCurrentQuestion(state.currentQuestion,false)};localStorage.setItem(key,JSON.stringify(snapshot));localStorage.setItem(activePointerKey(),JSON.stringify({key,name:state.studentName,id:state.studentId,profileMode:prof.mode,at:Date.now()}))}catch(e){if(state.currentQuestion?.phase==='genie')GM.TutorPanel.status('El navegador no permitió guardar el progreso local. Mantén esta ventana abierta.')}}
