function loadSaved(){const prof=userProfile();let local=null;try{local=JSON.parse(localStorage.getItem(saveKey())||'null')}catch(_){}const sameProfile=(a,b)=>a===b||(['student','teacher_tracked'].includes(a)&&['student','teacher_tracked'].includes(b));if(!local){try{const p=JSON.parse(localStorage.getItem(activePointerKey())||'null');if(p?.key&&sameProfile(p.profileMode,prof.mode))local=JSON.parse(localStorage.getItem(p.key)||'null')}catch(_){}}if(local&&Number(local.v)>=11&&!local.finished&&sameProfile(local.profileMode||prof.mode,prof.mode))return normalizeRestoredState(local);if(isTrackedLmsProfile()){try{const su=SCORM?.loadSuspend?.();if(Number(su?.v)>=7&&!su.fin&&sameProfile(su.pm||'student',prof.mode))return normalizeRestoredState(hydrateSuspend(su))}catch(_){}}return null}
function startTimers(){clearTimers();timerId=setInterval(()=>{if(!state.gameActive||state.finished)return;renderHUD();if(remainingSeconds()<=0)handleTimeout()},1000);autosaveId=setInterval(()=>{if(!state.gameActive||state.finished)return;saveLocal();scormPulse++;if(scormPulse%5===0&&isTrackedLmsProfile()){try{SCORM?.save?.(null,buildSuspend())}catch(_){}}},3000);emotionPulseId=setInterval(pulseEmotion,3600)}
function clearTimers(){if(timerId)clearInterval(timerId);if(autosaveId)clearInterval(autosaveId);if(emotionPulseId)clearInterval(emotionPulseId);if(emotionOverrideTimer)clearTimeout(emotionOverrideTimer);timerId=autosaveId=emotionPulseId=null;emotionOverrideTimer=null}
async function requestFullscreen(){const el=document.documentElement,fn=el.requestFullscreen||el.webkitRequestFullscreen;try{if(fn){await fn.call(el);state.fullscreenRequired=!!(document.fullscreenElement||document.webkitFullscreenElement);return state.fullscreenRequired}}catch(_){}return false}
