function enforceFullscreen(){const g=$('fullscreenGuard');if(g)g.classList.add('hidden');return true}
async function startNewGame(){if(loadSaved()?.awaitingFinalize){$('startError').textContent='Revisa el informe y cierra el intento terminado antes de comenzar otro.';return}if(studentAttemptBlocked()){$('startError').textContent='Este intento ya fue finalizado. Consulta el historial de informes.';return}if(isLmsStudent()&&loadSaved()){$('startError').textContent='Ya hay un intento iniciado. Usa Continuar juego guardado.';return}const id=identity(),prof=userProfile(),name=id.name||String($('studentName').value||'').trim();if(!name){$('startError').textContent='Escribe el nombre del estudiante.';return}state=freshState();state.profileMode=prof.mode;state.profileLabel=prof.label;state.selectedTopics=normalizeSelectedTopics(pendingTopics);state.studentName=name;state.studentId=id.id;state.startedAt=Date.now();state.deadlineAt=state.startedAt+TIME_LIMIT*1000;state.gameActive=true;state.grade=START_BANK;state.dealerScore=START_BANK;autoReportTriggered=false;currentReportHtml='';currentReportName='';finishPreparing=false;timeoutPending=false;state.firstButton=Math.random()<.5?'student':'dealer';try{SCORM?.beginAttempt?.()}catch(_){}document.body.classList.remove('start-mode','end-mode');document.body.classList.add('game-mode');$('startScreen').classList.remove('active');$('gameScreen').classList.remove('hidden');$('guideBand').classList.remove('hidden');$('hudStudent').textContent=name;startTimers();newHand();await requestFullscreen();state.fullscreenRequired=false;setGuideVisible(true);saveState(true);render()}
